ret = mix(ret,vec3(0.2,0.6, 1.0),tex2d(sampler_pc_main,moebius).y * 2.0);
ret = mix(ret, 0.0 ,GetBlur1(0.5 + (uv-0.5)*0.5).y * 2.0*(l));
ret = mix(ret,vec3( 1.0 , 1.0 , 1.0),tex2d(sampler_pc_main,moebius).x);
ret = mix(ret,vec3( 4.0 , 1.0 , 0.0),clamp01(tex2d(sampler_pc_main,0.5 + (uv-0.5)*0.2).y * 2.0*(l*l*l)));
ret = mix(ret,vec3(0.1, 0.0 , 0.0),clamp01(GetBlur1(0.5 + (uv-0.5)*0.2).x * 12.0));
ret = mix(ret,vec3(0.5,0.8, 1.0)*tex2d(sampler_pc_main,uv).z,clamp01(GetBlur1(0.5 + (uv-0.5)*0.2).x * 4.0)*1.4);
ret = mix(ret,vec3( 1.0 , 1.0 , 1.0),tex2d(sampler_pc_main,0.5 + (uv-0.5)*0.2).x);
